def is_billing_leap(year):
    """判断该年是否为计费闰年。"""
    return year % 4 == 0

verification_tests:
from target import is_billing_leap


def test_nineteenth_hundred_is_not_leap():
    assert is_billing_leap(1900) is False


def test_two_thousand_is_leap():
    assert is_billing_leap(2000) is True


def test_two_thousand_twenty_four_is_leap():
    assert is_billing_leap(2024) is True
